import pathlib
FILES = {
    'gradle.properties': 'org.gradle.jvmargs=-Xmx3G\norg.gradle.daemon=false\n\nminecraft_version=1.20.1\nminecraft_version_range=[1.20.1,1.21)\nforge_version=47.2.0\nforge_version_range=[47.2.0,)\nloader_version_range=[47,)\nmapping_channel=official\nmapping_version=1.20.1\n\nmod_id=fpvdrone\nmod_name=FPV Combat Drone\nmod_license=MIT\nmod_version=1.0.0\nmod_group_id=com.example.fpvdrone\nmod_authors=SeniorForgeDev\nmod_description=Tactical FPV combat drone with Acro-mode quaternion physics, GeckoLib 4 models, Betaflight OSD, and analog video interference.\n\ngeckolib_version=4.4.4\n',
    'src/main/java/com/example/fpvdrone/client/audio/SignalStaticSoundInstance.java': 'package com.example.fpvdrone.client.audio;\n\nimport com.example.fpvdrone.registry.ModSounds;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.resources.sounds.AbstractTickableSoundInstance;\nimport net.minecraft.client.resources.sounds.SoundInstance;\nimport net.minecraft.sounds.SoundSource;\n\npublic class SignalStaticSoundInstance extends AbstractTickableSoundInstance {\n    public SignalStaticSoundInstance() {\n        super(ModSounds.SIGNAL_STATIC_LOOP.get(), SoundSource.PLAYERS, SoundInstance.createUnseededRandom());\n        this.looping = true;\n        this.delay = 0;\n        this.volume = 0.45F;\n        this.pitch = 1.0F;\n        this.relative = true;\n    }\n\n    @Override\n    public void tick() {\n        if (Minecraft.getInstance().player == null) {\n            this.stop();\n        }\n    }\n\n    public void stopSound() {\n        this.stop();\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/client/renderer/FpvDroneModel.java': 'package com.example.fpvdrone.client.renderer;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport net.minecraft.resources.ResourceLocation;\nimport software.bernie.geckolib.model.GeoModel;\n\npublic class FpvDroneModel extends GeoModel<FpvDroneEntity> {\n    private static final ResourceLocation MODEL =\n            new ResourceLocation(FpvDroneMod.MODID, "geo/fpv_drone.geo.json");\n    private static final ResourceLocation TEXTURE =\n            new ResourceLocation(FpvDroneMod.MODID, "textures/entity/fpv_drone.png");\n    private static final ResourceLocation ANIMATION =\n            new ResourceLocation(FpvDroneMod.MODID, "animations/fpv_drone.animation.json");\n\n    @Override\n    public ResourceLocation getModelResource(FpvDroneEntity animatable) {\n        return MODEL;\n    }\n\n    @Override\n    public ResourceLocation getTextureResource(FpvDroneEntity animatable) {\n        return TEXTURE;\n    }\n\n    @Override\n    public ResourceLocation getAnimationResource(FpvDroneEntity animatable) {\n        return ANIMATION;\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/event/ServerEvents.java': 'package com.example.fpvdrone.event;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.capability.PlayerDroneCapability;\nimport com.example.fpvdrone.capability.PlayerDroneProvider;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport net.minecraft.server.level.ServerLevel;\nimport net.minecraft.server.level.ServerPlayer;\nimport net.minecraft.world.entity.Entity;\nimport net.minecraft.world.entity.player.Player;\nimport net.minecraftforge.common.capabilities.RegisterCapabilitiesEvent;\nimport net.minecraftforge.event.AttachCapabilitiesEvent;\nimport net.minecraftforge.event.entity.player.PlayerEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\n\n@Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, bus = Mod.EventBusSubscriber.Bus.FORGE)\npublic class ServerEvents {\n    @SubscribeEvent\n    public static void onAttachCapabilities(AttachCapabilitiesEvent<Entity> event) {\n        if (event.getObject() instanceof Player) {\n            if (!event.getObject().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).isPresent()) {\n                PlayerDroneProvider provider = new PlayerDroneProvider();\n                event.addCapability(PlayerDroneProvider.IDENTIFIER, provider);\n                event.addListener(provider::invalidate);\n            }\n        }\n    }\n\n    @SubscribeEvent\n    public static void onPlayerClone(PlayerEvent.Clone event) {\n        if (event.isWasDeath()) {\n            event.getOriginal().reviveCaps();\n            event.getOriginal().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(oldCap ->\n                    event.getEntity().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(newCap ->\n                            newCap.copyFrom(oldCap)));\n            event.getOriginal().invalidateCaps();\n        }\n    }\n\n    @SubscribeEvent\n    public static void onPlayerLoggedOut(PlayerEvent.PlayerLoggedOutEvent event) {\n        if (!(event.getEntity() instanceof ServerPlayer serverPlayer)) {\n            return;\n        }\n        serverPlayer.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(cap -> {\n            if (cap.isPiloting()) {\n                ServerLevel level = serverPlayer.serverLevel();\n                Entity drone = level.getEntity(cap.getBoundDroneEntityId());\n                if (drone instanceof FpvDroneEntity fpvDrone && !fpvDrone.isRemoved()) {\n                    fpvDrone.discard();\n                }\n                cap.clearBinding();\n            }\n        });\n    }\n\n    @Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)\n    public static class ModBusEvents {\n        @SubscribeEvent\n        public static void onRegisterCapabilities(RegisterCapabilitiesEvent event) {\n            event.register(PlayerDroneCapability.class);\n        }\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/item/FpvGogglesItem.java': 'package com.example.fpvdrone.item;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport net.minecraft.ChatFormatting;\nimport net.minecraft.nbt.CompoundTag;\nimport net.minecraft.network.chat.Component;\nimport net.minecraft.sounds.SoundEvent;\nimport net.minecraft.sounds.SoundEvents;\nimport net.minecraft.world.entity.Entity;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.item.ArmorItem;\nimport net.minecraft.world.item.ArmorMaterial;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.TooltipFlag;\nimport net.minecraft.world.item.crafting.Ingredient;\nimport net.minecraft.world.level.Level;\nimport org.jetbrains.annotations.Nullable;\n\nimport java.util.List;\nimport java.util.UUID;\n\npublic class FpvGogglesItem extends ArmorItem {\n    public static final String TAG_BOUND_DRONE = "BoundDroneUuid";\n\n    public static final ArmorMaterial GOGGLES_MATERIAL = new ArmorMaterial() {\n        @Override\n        public int getDurabilityForType(Type type) {\n            return 250;\n        }\n\n        @Override\n        public int getDefenseForType(Type type) {\n            return 2;\n        }\n\n        @Override\n        public int getEnchantmentValue() {\n            return 0;\n        }\n\n        @Override\n        public SoundEvent getEquipSound() {\n            return SoundEvents.ARMOR_EQUIP_IRON;\n        }\n\n        @Override\n        public Ingredient getRepairIngredient() {\n            return Ingredient.EMPTY;\n        }\n\n        @Override\n        public String getName() {\n            return FpvDroneMod.MODID + ":fpv_goggles";\n        }\n\n        @Override\n        public float getToughness() {\n            return 0.0F;\n        }\n\n        @Override\n        public float getKnockbackResistance() {\n            return 0.0F;\n        }\n    };\n\n    public FpvGogglesItem(ArmorMaterial material, Type type, Properties properties) {\n        super(material, type, properties);\n    }\n\n    @Override\n    public @Nullable String getArmorTexture(ItemStack stack, Entity entity, EquipmentSlot slot, String type) {\n        return FpvDroneMod.MODID + ":textures/models/armor/fpv_goggles_layer_1.png";\n    }\n\n    public static void setBoundDroneUuid(ItemStack stack, @Nullable UUID uuid) {\n        CompoundTag tag = stack.getOrCreateTag();\n        if (uuid != null) {\n            tag.putUUID(TAG_BOUND_DRONE, uuid);\n        } else {\n            tag.remove(TAG_BOUND_DRONE);\n        }\n    }\n\n    @Nullable\n    public static UUID getBoundDroneUuid(ItemStack stack) {\n        CompoundTag tag = stack.getTag();\n        if (tag != null && tag.hasUUID(TAG_BOUND_DRONE)) {\n            return tag.getUUID(TAG_BOUND_DRONE);\n        }\n        return null;\n    }\n\n    @Override\n    public void appendHoverText(ItemStack stack, @Nullable Level level, List<Component> tooltip, TooltipFlag flag) {\n        UUID bound = getBoundDroneUuid(stack);\n        if (bound != null) {\n            tooltip.add(Component.translatable("tooltip.fpvdrone.goggles_bound",\n                    bound.toString().substring(0, 8)).withStyle(ChatFormatting.GREEN));\n        } else {\n            tooltip.add(Component.translatable("tooltip.fpvdrone.goggles_unbound").withStyle(ChatFormatting.GRAY));\n        }\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/network/S2CDroneTelemetryPacket.java': 'package com.example.fpvdrone.network;\n\nimport com.example.fpvdrone.client.ClientDroneState;\nimport net.minecraft.network.FriendlyByteBuf;\nimport net.minecraftforge.api.distmarker.Dist;\nimport net.minecraftforge.fml.DistExecutor;\nimport net.minecraftforge.network.NetworkEvent;\n\nimport java.util.UUID;\nimport java.util.function.Supplier;\n\npublic class S2CDroneTelemetryPacket {\n    private final int droneEntityId;\n    private final UUID droneUuid;\n    private final float throttle;\n    private final float batteryVoltage;\n    private final int flightTicks;\n    private final boolean initialBind;\n\n    public S2CDroneTelemetryPacket(int droneEntityId, UUID droneUuid, float throttle,\n                                   float batteryVoltage, int flightTicks, boolean initialBind) {\n        this.droneEntityId = droneEntityId;\n        this.droneUuid = droneUuid;\n        this.throttle = throttle;\n        this.batteryVoltage = batteryVoltage;\n        this.flightTicks = flightTicks;\n        this.initialBind = initialBind;\n    }\n\n    public static void encode(S2CDroneTelemetryPacket msg, FriendlyByteBuf buf) {\n        buf.writeInt(msg.droneEntityId);\n        buf.writeUUID(msg.droneUuid);\n        buf.writeFloat(msg.throttle);\n        buf.writeFloat(msg.batteryVoltage);\n        buf.writeInt(msg.flightTicks);\n        buf.writeBoolean(msg.initialBind);\n    }\n\n    public static S2CDroneTelemetryPacket decode(FriendlyByteBuf buf) {\n        return new S2CDroneTelemetryPacket(\n                buf.readInt(),\n                buf.readUUID(),\n                buf.readFloat(),\n                buf.readFloat(),\n                buf.readInt(),\n                buf.readBoolean()\n        );\n    }\n\n    public static void handle(S2CDroneTelemetryPacket msg, Supplier<NetworkEvent.Context> ctxSupplier) {\n        NetworkEvent.Context ctx = ctxSupplier.get();\n        DistExecutor.unsafeRunWhenOn(Dist.CLIENT, () -> () ->\n                ClientDroneState.onTelemetryReceived(\n                        msg.droneEntityId,\n                        msg.droneUuid,\n                        msg.throttle,\n                        msg.batteryVoltage,\n                        msg.flightTicks,\n                        msg.initialBind\n                ));\n        ctx.setPacketHandled(true);\n    }\n}\n',
    'src/main/resources/assets/fpvdrone/models/item/fpv_goggles.json': '{\n  "parent": "minecraft:item/generated",\n  "textures": {\n    "layer0": "fpvdrone:item/fpv_goggles"\n  }\n}\n',
    'generate_assets.py': 'import os\nimport math\nimport struct\nimport wave\nimport subprocess\nfrom pathlib import Path\nfrom PIL import Image, ImageDraw\n\nBASE = Path(".")\nASSETS = BASE / "src/main/resources/assets/fpvdrone"\n\nfor sub in [\n    "textures/entity",\n    "textures/item",\n    "textures/models/armor",\n    "sounds",\n    "geo",\n    "animations",\n    "lang",\n    "models/item",\n]:\n    (ASSETS / sub).mkdir(parents=True, exist_ok=True)\n\n\ndef make_drone_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (28, 30, 34, 255))\n    draw = ImageDraw.Draw(img)\n    # Carbon fiber weave pattern across background (0..64, 0..64)\n    for y in range(0, 128, 4):\n        for x in range(0, 128, 4):\n            c = 38 if ((x // 4 + y // 4) % 2 == 0) else 24\n            draw.rectangle([x, y, x + 3, y + 3], fill=(c, c + 2, c + 5, 255))\n    # Warhead olive drab & brass band region (64..128, 0..64)\n    draw.rectangle([64, 0, 127, 63], fill=(68, 78, 46, 255))\n    draw.rectangle([64, 20, 127, 26], fill=(195, 165, 55, 255))  # HE band\n    draw.rectangle([64, 48, 127, 63], fill=(95, 98, 102, 255))  # Fuze tip\n    # Camera lens region (0..64, 64..128)\n    draw.rectangle([0, 64, 63, 127], fill=(18, 20, 24, 255))\n    draw.ellipse([12, 76, 52, 116], fill=(10, 35, 65, 255), outline=(90, 100, 115, 255), width=2)\n    draw.ellipse([22, 86, 36, 100], fill=(70, 170, 230, 255))\n    # Propellers & motor bells (64..128, 64..128)\n    draw.rectangle([64, 64, 127, 127], fill=(42, 44, 48, 255))\n    draw.rectangle([64, 96, 127, 127], fill=(190, 50, 35, 255))  # Red/orange prop tips\n    img.save(path)\n\n\ndef make_drone_item_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    # 4 arms (X-frame)\n    draw.line([(20, 20), (108, 108)], fill=(45, 48, 54, 255), width=10)\n    draw.line([(108, 20), (20, 108)], fill=(45, 48, 54, 255), width=10)\n    # Propellers\n    for cx, cy in [(22, 22), (106, 22), (22, 106), (106, 106)]:\n        draw.ellipse([cx - 18, cy - 18, cx + 18, cy + 18], outline=(210, 60, 40, 220), width=4)\n        draw.ellipse([cx - 6, cy - 6, cx + 6, cy + 6], fill=(160, 165, 175, 255))\n    # Central body + warhead\n    draw.rectangle([48, 40, 80, 88], fill=(32, 34, 38, 255), outline=(90, 95, 105, 255), width=2)\n    draw.rectangle([54, 28, 74, 50], fill=(72, 84, 48, 255))  # Warhead nose\n    draw.rectangle([58, 22, 70, 28], fill=(200, 165, 50, 255))\n    img.save(path)\n\n\ndef make_goggles_item_texture(path: Path):\n    img = Image.new("RGBA", (128, 128), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    # Strap\n    draw.rectangle([10, 48, 118, 76], fill=(35, 38, 42, 255))\n    # Main goggle housing\n    draw.rounded_rectangle([20, 36, 108, 92], radius=12, fill=(52, 56, 62, 255), outline=(110, 118, 128, 255), width=3)\n    # Dual screens/lenses\n    draw.rounded_rectangle([28, 48, 58, 80], radius=6, fill=(15, 45, 75, 255), outline=(0, 210, 180, 255), width=2)\n    draw.rounded_rectangle([70, 48, 100, 80], radius=6, fill=(15, 45, 75, 255), outline=(0, 210, 180, 255), width=2)\n    # Antennas\n    draw.rectangle([28, 14, 34, 36], fill=(25, 25, 28, 255))\n    draw.ellipse([25, 8, 37, 20], fill=(210, 55, 40, 255))\n    draw.rectangle([94, 18, 100, 36], fill=(25, 25, 28, 255))\n    img.save(path)\n\n\ndef make_goggles_armor_layer(path: Path):\n    img = Image.new("RGBA", (128, 64), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(img)\n    # Helmet band around head UV (0..64, 0..32)\n    draw.rectangle([0, 18, 63, 28], fill=(35, 38, 42, 255))\n    # Front visor\n    draw.rectangle([16, 14, 32, 30], fill=(48, 52, 58, 255))\n    draw.rectangle([18, 17, 23, 26], fill=(0, 200, 175, 255))\n    draw.rectangle([25, 17, 30, 26], fill=(0, 200, 175, 255))\n    img.save(path)\n\n\ndef write_wav_and_convert_ogg(wav_path: Path, ogg_path: Path, sample_rate: int, samples):\n    with wave.open(str(wav_path), "w") as wf:\n        wf.setnchannels(2)\n        wf.setsampwidth(2)\n        wf.setframerate(sample_rate)\n        frames = bytearray()\n        for l, r in samples:\n            li = max(-32767, min(32767, int(l * 32767)))\n            ri = max(-32767, min(32767, int(r * 32767)))\n            frames.extend(struct.pack("<hh", li, ri))\n        wf.writeframes(bytes(frames))\n    subprocess.run(\n        ["ffmpeg", "-y", "-i", str(wav_path), "-c:a", "libvorbis", "-q:a", "6", str(ogg_path)],\n        check=True,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.DEVNULL,\n    )\n    wav_path.unlink()\n\n\ndef generate_sounds():\n    sr = 44100\n    # 1. drone_motor_loop.ogg (2.0s seamless brushless motor buzz)\n    n1 = sr * 2\n    s1 = []\n    for i in range(n1):\n        t = i / sr\n        v = (\n            0.35 * math.sin(2 * math.pi * 180.0 * t)\n            + 0.25 * math.sin(2 * math.pi * 360.0 * t)\n            + 0.15 * math.sin(2 * math.pi * 540.0 * t)\n            + 0.08 * math.sin(2 * math.pi * 720.0 * t)\n        )\n        s1.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp1.wav", ASSETS / "sounds/drone_motor_loop.ogg", sr, s1)\n\n    # 2. drone_arm_beep.ogg (0.45s classic 3-tone ESC arming chime)\n    n2 = int(sr * 0.45)\n    s2 = []\n    for i in range(n2):\n        t = i / sr\n        freq = 1200.0 if t < 0.12 else (1600.0 if t < 0.24 else 2200.0)\n        env = 1.0 if (t % 0.14) < 0.10 else 0.0\n        v = 0.5 * env * math.sin(2 * math.pi * freq * t)\n        s2.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp2.wav", ASSETS / "sounds/drone_arm_beep.ogg", sr, s2)\n\n    # 3. signal_static_loop.ogg (1.5s analog white/pink static)\n    import random\n    rng = random.Random(42)\n    n3 = int(sr * 1.5)\n    s3 = [(rng.uniform(-0.35, 0.35), rng.uniform(-0.35, 0.35)) for _ in range(n3)]\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp3.wav", ASSETS / "sounds/signal_static_loop.ogg", sr, s3)\n\n    # 4. drone_explosion.ogg (1.0s low-end boom + crackle)\n    n4 = sr\n    s4 = []\n    for i in range(n4):\n        t = i / sr\n        env = math.exp(-4.5 * t)\n        boom = math.sin(2 * math.pi * (90.0 * math.exp(-3.0 * t) + 28.0) * t)\n        noise = rng.uniform(-0.6, 0.6) * math.exp(-7.0 * t)\n        v = max(-1.0, min(1.0, env * (0.75 * boom + noise)))\n        s4.append((v, v))\n    write_wav_and_convert_ogg(ASSETS / "sounds/tmp4.wav", ASSETS / "sounds/drone_explosion.ogg", sr, s4)\n\n\nif __name__ == "__main__":\n    make_drone_texture(ASSETS / "textures/entity/fpv_drone.png")\n    make_drone_item_texture(ASSETS / "textures/item/fpv_drone_item.png")\n    make_goggles_item_texture(ASSETS / "textures/item/fpv_goggles.png")\n    make_goggles_armor_layer(ASSETS / "textures/models/armor/fpv_goggles_layer_1.png")\n    generate_sounds()\n    print("Assets generated successfully.")\n',
}
for k, v in FILES.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Wrote", len(FILES), "files")
